fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let mut result = Vec::new();
    
    for (i, &number) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(delim); // Add delimiter before every element except the first
        }
        result.push(number); // Add the current element
    }
    
    result
}